create or replace function public.my_lead_folders() returns table(lead_type text, lead_count bigint) language sql stable security invoker set search_path = '' as $$ select l.lead_type,count(*) from public.leads l where l.assigned_to=(select auth.uid()) and l.status='assigned' and (select public.is_active_agent()) and (select auth.jwt()->>'aal')='aal2' group by l.lead_type order by l.lead_type nulls last $$; revoke all on function public.my_lead_folders() from public,anon; grant execute on function public.my_lead_folders() to authenticated; create index leads_agent_type_dead_last_idx on public.leads(assigned_to,lead_type,is_dead_number,assigned_at desc,id desc) where status='assigned';